package local.tvmorph.tv;
import android.content.Context;import android.database.Cursor;import android.net.Uri;import android.provider.DocumentsContract;import android.provider.OpenableColumns;
import org.json.*;import java.util.*;
/** Only content URIs granted through the system picker; no broad storage permission. */
final class LocalMediaQueue {
 static final int LIMIT=200;
 static String name(Context context,Uri uri){try(Cursor rows=context.getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(rows!=null&&rows.moveToFirst())return rows.getString(0);}catch(RuntimeException ignored){}return uri.getLastPathSegment();}
 static JSONObject row(Context context,Uri uri)throws Exception{String name=name(context,uri),mime=UsbMediaTypes.resolve(context.getContentResolver().getType(uri),name);if(mime==null||!mime.startsWith("video/"))return null;return new JSONObject().put("uri",uri.toString()).put("name",name).put("mime",mime);}
 static JSONArray selected(Context context,List<Uri> uris)throws Exception{JSONArray rows=new JSONArray();Set<String> seen=new HashSet<>();for(Uri uri:uris){if(rows.length()>=LIMIT)break;if(uri==null||!"content".equals(uri.getScheme())||!seen.add(uri.toString()))continue;JSONObject row=row(context,uri);if(row!=null)rows.put(row);}return clean(rows);}
 static JSONArray clean(JSONArray source)throws Exception{JSONArray rows=new JSONArray();int characters=0;Set<String> seen=new HashSet<>();if(source==null)return rows;for(int i=0;i<source.length()&&rows.length()<LIMIT;i++){JSONObject row=source.optJSONObject(i);if(row==null)continue;String address=row.optString("uri"),name=row.optString("name","Video");Uri uri=Uri.parse(address);String mime=UsbMediaTypes.resolve(row.optString("mime"),name);if(!"content".equals(uri.getScheme())||uri.getAuthority()==null||address.length()>4000||mime==null||!mime.startsWith("video/")||!seen.add(address))continue;JSONObject clean=new JSONObject().put("uri",address).put("name",name.substring(0,Math.min(250,name.length()))).put("mime",mime);characters+=clean.toString().length();if(characters>80000)break;rows.put(clean);}return rows;}
 static android.content.ClipData grants(JSONArray rows)throws Exception{android.content.ClipData clip=android.content.ClipData.newRawUri("Selected videos",Uri.parse(rows.getJSONObject(0).getString("uri")));for(int i=1;i<rows.length();i++)clip.addItem(new android.content.ClipData.Item(Uri.parse(rows.getJSONObject(i).getString("uri"))));return clip;}
 static int natural(String a,String b){int i=0,j=0;while(i<a.length()&&j<b.length()){char x=a.charAt(i),y=b.charAt(j);if(Character.isDigit(x)&&Character.isDigit(y)){int ai=i,bj=j;while(i<a.length()&&Character.isDigit(a.charAt(i)))i++;while(j<b.length()&&Character.isDigit(b.charAt(j)))j++;String ax=a.substring(ai,i).replaceFirst("^0+(?!$)",""),by=b.substring(bj,j).replaceFirst("^0+(?!$)","");int result=ax.length()!=by.length()?Integer.compare(ax.length(),by.length()):ax.compareTo(by);if(result!=0)return result;}else{int result=Character.compare(Character.toLowerCase(x),Character.toLowerCase(y));if(result!=0)return result;i++;j++;}}return Integer.compare(a.length()-i,b.length()-j);}
 static JSONArray folder(Context context,Uri tree)throws Exception{if(tree==null||!"content".equals(tree.getScheme())||!DocumentsContract.isTreeUri(tree))throw new IllegalArgumentException("Choose a video folder");String parent=DocumentsContract.getTreeDocumentId(tree);Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,parent);List<JSONObject> found=new ArrayList<>();String[] fields={DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE};try(Cursor cursor=context.getContentResolver().query(children,fields,null,null,null)){int scanned=0;while(cursor!=null&&cursor.moveToNext()&&scanned++<2000){String name=cursor.getString(1),mime=UsbMediaTypes.resolve(cursor.getString(2),name);if(mime==null||!mime.startsWith("video/"))continue;found.add(new JSONObject().put("uri",DocumentsContract.buildDocumentUriUsingTree(tree,cursor.getString(0)).toString()).put("name",name).put("mime",mime));}}Collections.sort(found,(a,b)->natural(a.optString("name"),b.optString("name")));JSONArray rows=new JSONArray();for(int i=0;i<Math.min(LIMIT,found.size());i++)rows.put(found.get(i));return clean(rows);}
 private LocalMediaQueue(){}
}
